# Initially generated by GitHub Copilot.
import unittest

from author_util import json_block


class TestAuthorJsonBlock(unittest.TestCase):
    def test_mask_verify_wildcards_maps_expected_placeholders(self):
        src = """{
  "header": {"__verify_mp_any_dict__": true},
  "book39s": {"__verify_mp_any_list__": true},
  "value": {"__verify_mp_any_string_dict_or_list__": true}
}"""

        masked = json_block._mask_verify_wildcards_for_display(src)

        self.assertIn('"header": {...}', masked)
        self.assertIn('"book39s": [...]', masked)
        self.assertIn('"value": ...', masked)
        self.assertNotIn("__verify_mp_any_", masked)

    def test_mask_verify_wildcards_replaces_token_form(self):
        src = '{"k": "__verify_mp_any_value__", "k2": {"__verify_mp_any_string_dict_or_list__": true}}'

        masked = json_block._mask_verify_wildcards_for_display(src)

        self.assertNotIn("__verify_mp_any_", masked)
        self.assertIn('"k": ...', masked)
        self.assertIn('"k2": ...', masked)

    def test_json_block_with_notes_masks_markers_in_html(self):
        src = '{"header": {"__verify_mp_any_dict__": true}}'

        html = json_block.json_block_with_notes_raw_html(src, {1: "top-level note"})
        raw_html = html["_raw_html"] if isinstance(html, dict) else html

        self.assertNotIn("__verify_mp_any_", raw_html)
        self.assertIn('<span class="ellipsis">...</span>', raw_html)
        self.assertNotIn(
            '<span class="tok-punct">.</span><span class="tok-punct">.</span><span class="tok-punct">.</span>',
            raw_html,
        )
        self.assertIn('class="ln"', raw_html)
        self.assertIn("top-level note", raw_html)

    def test_mask_verify_wildcards_unwraps_wildcard_string_marker(self):
        src = '{"k": {"__verify_mp_wildcard_string__": "והיה מדי ... אמר יהוה"}}'

        masked = json_block._mask_verify_wildcards_for_display(src)

        self.assertNotIn("__verify_mp_wildcard_string__", masked)
        self.assertIn('"k": "והיה מדי ... אמר יהוה"', masked)


if __name__ == "__main__":
    unittest.main()
